<script setup>
import { computed, ref, reactive, watch } from 'vue';
import { Head, Link, router, usePage } from '@inertiajs/vue3';
import AppLayout from '../../layouts/AppLayout.vue';
import HubNav from './HubNav.vue';
import './hub.css';
const props=defineProps({leads:Object,filters:Object,stats:Object,options:Object});
const page=usePage();const user=computed(()=>page.props.auth.user);
const presets=[['manual','Ручной поиск'],['hot','Горячие лиды'],['it','Руководители IT'],['messenger','Лиды для мессенджера'],['procurement','Закупки и тендеры'],['free','Свободные лиды'],['due','Повторные касания'],['duplicates','Возможные дубли'],['quality','Проверка качества']];
const fresh=()=>({q:'',company:'',company_mode:'contains',titles:['','',''],title_mode:'contains',groups:[],holding:'',industry:'',status:'',priority:'',owner:'',min_score:0,email:false,phone:false,messenger:false,social:false,check:false,preset:'manual',company_id:''});
const state=reactive(fresh());
function sync(){Object.assign(state,fresh(),props.filters);state.titles=[...(props.filters.titles||[]),'','',''].slice(0,3);for(const k of ['email','phone','messenger','social','check'])state[k]=['1',1,true].includes(state[k]);}
sync();watch(()=>props.filters,sync,{deep:true});
const advanced=ref(false);const busy=ref(false);const error=ref('');const detail=ref(null);const addOpen=ref(false);const saving=ref(false);
const edit=reactive({version:0,status:'Новый',priority:'Не назначен',next_action:'',next_at:'',comment:'',take:false,owner_id:''});
const blank=()=>({full_name:'',company_raw:'',title:'',email:'',phone:'',messenger:'',social:''});
const newLead=reactive(blank());
const identityOpen=ref(false);const identity=reactive(blank());
const canIdentity=computed(()=>detail.value&&(user.value.role==='admin'||Number(detail.value.owner_id)===Number(user.value.id)));
function startIdentity(){for(const k of Object.keys(identity))identity[k]=detail.value[k]||'';identityOpen.value=true;error.value='';}
async function saveIdentity(){saving.value=true;error.value='';try{const id=detail.value.id;await api('/projects/sales-hub/leads/'+id+'/identity',{method:'PATCH',body:JSON.stringify({...identity,version:detail.value.version})});identityOpen.value=false;router.reload({only:['leads','stats']});await open(id);}catch(e){error.value=e.message;}finally{saving.value=false;}}
function exportLeads(){const p=new URLSearchParams();for(const [k,v] of Object.entries(query())){if(k==='page')continue;if(Array.isArray(v))v.forEach(x=>p.append(k+'[]',x));else p.set(k,v);}window.location.assign('/projects/sales-hub/export?'+p);}
const num=v=>Number(v||0).toLocaleString('ru-RU');
function query(p=1){const d={...state,page:p};for(const k of ['email','phone','messenger','social','check'])d[k]=d[k]?1:0;d.titles=d.titles.filter(Boolean);for(const k of Object.keys(d))if(d[k]===''||d[k]===null||d[k]===undefined||Array.isArray(d[k])&&!d[k].length)delete d[k];return d;}
function search(p=1){router.get('/projects/sales-hub',query(p),{preserveScroll:true,preserveState:true,replace:true,onStart:()=>busy.value=true,onFinish:()=>busy.value=false});}
function preset(v){state.preset=v;search();}
function reset(){Object.assign(state,fresh());search();}
async function api(url,opts={}){const r=await fetch(url,{...opts,credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':page.props.csrfToken}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||'Ошибка запроса: '+r.status);return d;}
const canEdit=computed(()=>detail.value&&(user.value.role==='admin'||Number(detail.value.owner_id)===Number(user.value.id)||(!detail.value.owner_id&&['','Не назначен'].includes(detail.value.owner_raw))));
const isFree=computed(()=>detail.value&&!detail.value.owner_id&&['','Не назначен'].includes(detail.value.owner_raw));
async function open(id){error.value='';try{const d=await api('/projects/sales-hub/leads/'+id);detail.value=d;identityOpen.value=false;Object.assign(edit,{version:d.version,status:d.status,priority:d.priority,next_action:d.next_action,next_at:d.next_at||'',comment:d.comment,take:isFree.value,owner_id:d.owner_id||''});}catch(e){error.value=e.message;}}
async function save(){saving.value=true;error.value='';try{const data={...edit,next_at:edit.next_at||null};if(user.value.role==='admin')data.owner_id=edit.owner_id||null;else delete data.owner_id;await api('/projects/sales-hub/leads/'+detail.value.id,{method:'PATCH',body:JSON.stringify(data)});detail.value=null;router.reload({only:['leads','stats']});}catch(e){error.value=e.message;}finally{saving.value=false;}}
async function create(){saving.value=true;error.value='';try{const d=await api('/projects/sales-hub/leads',{method:'POST',body:JSON.stringify(newLead)});addOpen.value=false;Object.assign(newLead,blank());router.reload({only:['leads','stats']});await open(d.id);}catch(e){error.value=e.message;}finally{saving.value=false;}}
const firstEmail=v=>(v||'').split(';').map(x=>x.trim()).find(x=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(x));
const firstPhone=v=>(v||'').split(';').map(x=>x.replace(/[^+\d]/g,'')).find(x=>/^\+?\d{9,15}$/.test(x));
const firstMessenger=v=>{for(const x of (v||'').split(';')){const t=x.trim().replace(/^Telegram\s*/i,'');if(/^@[a-zA-Z0-9_]{3,}$/.test(t))return 'https://t.me/'+t.slice(1);try{const u=new URL(t);if(u.protocol==='https:'&&['t.me','telegram.me','wa.me','api.whatsapp.com','web.whatsapp.com'].includes(u.hostname))return u.href;}catch{}}return null;};
function scoreClass(n){return n>=80?'a':n>=60?'b':n>=40?'c':'d';}
</script>
<template><Head title="Контакты"/><AppLayout><div class="saleshub"><HubNav/><div class="page-head"><div><p class="eyebrow">ЛИДОГЕНЕРАЦИЯ</p><h1>Рабочая база</h1><p class="muted">Поиск, отбор и работа с ЛПР</p></div><div class="actions"><button v-if="user.role==='admin'" @click="exportLeads">Экспорт CSV</button><button class="primary" @click="addOpen=true;error=''">+ Контакт</button></div></div>
<div class="metrics"><div v-for="[label,value] in [['Всего контактов',stats.total],['Есть канал связи',stats.reachable],['Горячие лиды',stats.hot],['Свободные',stats.free]]" :key="label" class="metric"><small>{{label}}</small><strong>{{num(value)}}</strong></div></div>
<div class="panel filters"><div class="preset-row"><button v-for="[v,label] in presets" :key="v" :class="{active:state.preset===v}" @click="preset(v)">{{label}}</button></div><p v-if="state.preset!=='manual'" class="muted">Сценарий заменяет ручные условия; фильтр ответственного остаётся активным.</p>
<form @submit.prevent="state.preset='manual';search()"><div class="filter-grid"><label>Поиск<input v-model="state.q" placeholder="ФИО, компания, должность"></label><label>Компания<input v-model="state.company" placeholder="Например, Сбер"></label><label>Должность<input v-model="state.titles[0]" placeholder="CIO, CTO"></label><label>Ответственный<select v-model="state.owner" @change="search()"><option value="">Все</option><option value="mine">Мои лиды</option><option value="free">Свободные</option><option v-for="o in options.owners" :key="o.id" :value="String(o.id)">{{o.name}}</option></select></label></div>
<div v-if="advanced" class="filter-grid advanced"><label>Режим компании<select v-model="state.company_mode"><option value="contains">Содержит</option><option value="exact">Точное совпадение</option></select></label><label>Должность 2<input v-model="state.titles[1]"></label><label>Должность 3<input v-model="state.titles[2]"></label><label>Режим должности<select v-model="state.title_mode"><option value="contains">Содержит</option><option value="exact">Точное совпадение</option></select></label><label>Группа ЛПР (ИЛИ)<select v-model="state.groups" multiple size="4"><option v-for="g in options.groups" :key="g">{{g}}</option></select></label><label>Холдинг<select v-model="state.holding"><option value="">Любой</option><option v-for="h in options.holdings" :key="h">{{h}}</option></select></label><label>Отрасль<select v-model="state.industry"><option value="">Любая</option><option v-for="i in options.industries" :key="i">{{i}}</option></select></label><label>Статус<select v-model="state.status"><option value="">Любой</option><option v-for="s in options.statuses" :key="s">{{s}}</option></select></label><label>Приоритет<select v-model="state.priority"><option value="">Любой</option><option v-for="p in options.priorities" :key="p">{{p}}</option></select></label><label>Минимальный балл<input v-model.number="state.min_score" type="number" min="0" max="100"></label><div class="checks"><label v-for="[key,label] in [['email','Почта'],['phone','Телефон'],['messenger','Мессенджер'],['social','Соцсети'],['check','На проверку']]" :key="key"><input type="checkbox" v-model="state[key]"> {{label}}</label></div></div>
<div class="actions"><button class="primary" :disabled="busy">Найти</button><button type="button" @click="advanced=!advanced">{{advanced?'Свернуть':'Расширенный поиск'}}</button><button type="button" @click="reset">Сбросить</button></div></form></div>
<div v-if="error&&!detail&&!addOpen" class="notice error">{{error}}</div><div class="result-head"><strong>{{num(leads.total)}} контактов</strong><div class="actions"><button :disabled="leads.current_page<=1" @click="search(leads.current_page-1)">←</button><span>{{leads.current_page}} / {{leads.last_page}}</span><button :disabled="leads.current_page>=leads.last_page" @click="search(leads.current_page+1)">→</button></div></div>
<div class="table-scroll"><table><thead><tr><th>Контакт</th><th>Компания</th><th>Должность</th><th>Балл</th><th>Статус</th><th>Ответственный</th><th>Связь</th></tr></thead><tbody><tr v-for="x in leads.data" :key="x.id"><td><button class="text-link" @click="open(x.id)">{{x.full_name}}</button><small v-if="x.possible_duplicate" class="warn">Возможный дубль</small><small v-if="x.quality_check" class="warn">Проверить данные</small></td><td><Link v-if="x.company_id" :href="'/projects/sales-hub/companies?id='+x.company_id">{{x.company_raw}}</Link><span v-else>—</span><small v-if="x.company_claimed" class="warn">Компания уже в работе</small></td><td>{{x.title||'—'}}<small>{{x.groups.join(' · ')}}</small></td><td><span :class="'score '+scoreClass(x.score)">{{x.score}}</span></td><td>{{x.status}}<small>{{x.priority}}</small></td><td>{{x.owner_name||x.owner_raw||'Свободен'}}<small>{{x.next_at||''}}</small></td><td><div class="links"><a v-if="firstEmail(x.email)" :href="'mailto:'+firstEmail(x.email)">Почта</a><a v-if="firstPhone(x.phone)" :href="'tel:'+firstPhone(x.phone)">Тел.</a><a v-if="firstMessenger(x.messenger)" :href="firstMessenger(x.messenger)" target="_blank" rel="noopener noreferrer">Чат</a></div></td></tr><tr v-if="!leads.data.length"><td colspan="7" class="empty">Контакты не найдены</td></tr></tbody></table></div>
<div v-if="detail" class="overlay" @click.self="detail=null"><section class="drawer" role="dialog" aria-modal="true" aria-label="Карточка контакта"><div class="page-head"><div><p class="eyebrow">КОНТАКТ #{{detail.id}}</p><h2>{{detail.full_name}}</h2></div><button @click="detail=null" aria-label="Закрыть">×</button></div><p>{{detail.company_raw}} · {{detail.title}}</p><p v-if="detail.possible_duplicate" class="notice warn">Совпадение канала связи с другим контактом. Проверьте перед обращением.</p><p v-if="detail.company_claimed" class="notice warn">С компанией уже может работать коллега.</p><dl><dt>Почта</dt><dd>{{detail.email||'—'}}</dd><dt>Телефон</dt><dd>{{detail.phone||'—'}}</dd><dt>Мессенджер</dt><dd>{{detail.messenger||'—'}}</dd><dt>Соцсети</dt><dd>{{detail.social||'—'}}</dd></dl><button v-if="canIdentity&&!identityOpen" @click="startIdentity">Редактировать контактные данные</button><form v-if="identityOpen" @submit.prevent="saveIdentity"><label v-for="[k,label] in [['full_name','ФИО'],['company_raw','Компания'],['title','Должность'],['email','Почта'],['phone','Телефон'],['messenger','Мессенджер'],['social','Соцсети']]" :key="k">{{label}}<input v-model="identity[k]" :required="k==='full_name'"></label><div class="actions"><button class="primary" :disabled="saving">Сохранить данные</button><button type="button" @click="identityOpen=false">Отмена</button></div></form><form v-else @submit.prevent="save"><fieldset :disabled="!canEdit||saving"><div class="filter-grid"><label>Статус<select v-model="edit.status"><option v-for="s in options.statuses" :key="s">{{s}}</option></select></label><label>Приоритет<select v-model="edit.priority"><option v-for="p in options.priorities" :key="p">{{p}}</option></select></label></div><label>Следующее действие<input v-model="edit.next_action"></label><label>Дата касания<input v-model="edit.next_at" type="date"></label><label>Комментарий<textarea v-model="edit.comment" rows="4"></textarea></label><label v-if="user.role==='admin'">Ответственный<select v-model="edit.owner_id"><option value="">Не назначен</option><option v-for="o in options.owners" :key="o.id" :value="o.id">{{o.name}}</option></select></label><label v-if="isFree"><input v-model="edit.take" type="checkbox"> Взять в работу</label><button v-if="canEdit" class="primary">Сохранить</button><p v-else class="muted">Контакт закреплён за другим сотрудником.</p></fieldset></form><p v-if="error" class="error">{{error}}</p><h3>История изменений</h3><div v-for="(h,i) in detail.history" :key="i" class="history"><strong>{{h.name}}</strong> · {{h.created_at}}<small>Изменены рабочие поля</small></div></section></div><div v-if="addOpen" class="overlay" @click.self="addOpen=false"><section class="drawer" role="dialog" aria-modal="true" aria-label="Новый контакт"><div class="page-head"><h2>Новый контакт</h2><button @click="addOpen=false">×</button></div><form @submit.prevent="create"><label v-for="[k,label] in [['full_name','ФИО'],['company_raw','Компания'],['title','Должность'],['email','Почта'],['phone','Телефон'],['messenger','Мессенджер'],['social','Соцсети']]" :key="k">{{label}}<input v-model="newLead[k]" :required="k==='full_name'"></label><button class="primary" :disabled="saving">Создать</button><p v-if="error" class="error">{{error}}</p></form></section></div>
</div></AppLayout></template>
